INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('e9f664d8-c41d-429f-bf0d-191c4de5ba5e', 'cbam-actual-or-default-e9f664d8', 'en', 'Actual or default? The CBAM data decision for Turkish metal exporters', 'Why the emissions question has moved from your EU buyer’s compliance desk into your commercial negotiation.', 'Actual or default', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'October 2026', 4, 12, 'Why the emissions question has moved from your EU buyer’s compliance desk into your commercial negotiation.', 'The definitive CBAM regime has applied since 1 January 2026. EU importers bringing in more than 50 tonnes of covered goods a year must be authorised CBAM declarants, and the first annual declaration covering 2026 imports falls in 2027.', 'The definitive CBAM regime has applied since 1 January 2026. EU importers bringing in more than 50 tonnes of covered goods a year must be authorised CBAM declarants, and the first annual declaration covering 2026 imports falls in 2027. For a Turkish iron, steel or aluminium supplier, the practical question is no longer whether CBAM applies. It is whether to give EU buyers verified actual emissions data, or let them rely on default values. That is a commercial decision with a data cost, not a reporting chore. Actual values are not automatically cheaper for anyone. The answer depends on the production route, the quality of plant data, the cost of independent verification, and how the contract shares the CBAM cost between buyer and supplier.', '[{"title": "The regime is live", "explanation": "The definitive CBAM regime has applied since 1 January 2026. EU importers bringing in more than 50 tonnes of covered goods a year must be authorised CBAM declarants, and the first annual declaration covering 2026 imports falls in 2027.", "page": 2}, {"title": "The question is commercial", "explanation": "For a Turkish iron, steel or aluminium supplier, the practical question is no longer whether CBAM applies. It is whether to give EU buyers verified actual emissions data, or let them rely on default values. That is a commercial decision with a data cost, not a reporting chore.", "page": 2}, {"title": "Actual is not automatically cheaper", "explanation": "Actual values are not automatically cheaper for anyone. The answer depends on the production route, the quality of plant data, the cost of independent verification, and how the contract shares the CBAM cost between buyer and supplier.", "page": 2}]', '[]', '["Which of our EU customers are above the threshold, and which have asked or will ask for actual data?", "Which products and production routes carry most of our EU volume?", "Is our installation boundary clear, and are production routes separated in our records?", "Where do energy, production and precursor data sit today, and who owns each source?", "What would independent verification cost relative to the volume it would cover?", "How do our contracts allocate CBAM cost, and is that open to renegotiation?", "Do our precursor suppliers provide emissions data we can rely on?", "Who in our business owns the CBAM conversation with buyers?"]', 'Desk review of official EU and Turkish sources checked on 21–23 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["CBAM", "Carbon", "EU market access"]', '["Market entry"]', '["CBAM", "emissions", "steel", "aluminium", "EU importer"]', 'fully_ungated', 'pdf-insights/e9f664d8-c41d-429f-bf0d-191c4de5ba5e/v1/Ganrich-CBAM-Actual-or-Default-EN.pdf', 'Ganrich-CBAM-Actual-or-Default-EN.pdf', '225f55c9fe13c6ca22f6ca96e7a9edad030d6f675c2b63e2970e7f43f050d5ad', 'application/pdf', 254722, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000001', 'e9f664d8-c41d-429f-bf0d-191c4de5ba5e', 1, 'pdf-insights/e9f664d8-c41d-429f-bf0d-191c4de5ba5e/v1/Ganrich-CBAM-Actual-or-Default-EN.pdf', 'Ganrich-CBAM-Actual-or-Default-EN.pdf', '225f55c9fe13c6ca22f6ca96e7a9edad030d6f675c2b63e2970e7f43f050d5ad', 254722, 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('96989394-d12c-40aa-a891-e6e5a54dbb6b', 'cra-the-24-hour-test-96989394', 'en', 'The 24-hour test: CRA incident readiness for manufacturers selling into the EU', 'Reporting duties under the Cyber Resilience Act began on 11 September 2026. The hard part is not the form. It is knowing, within hours, what happened and who decides.', 'The 24-hour test', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'October 2026', 4, 12, 'Reporting duties under the Cyber Resilience Act began on 11 September 2026. The hard part is not the form. It is knowing, within hours, what happened and who decides.', 'Since 11 September 2026, manufacturers of products with digital elements sold in the EU must report actively exploited vulnerabilities and severe incidents affecting the security of their products: an early warning within 24 hours and a notification within 72 hours, followed by a final report.', 'Since 11 September 2026, manufacturers of products with digital elements sold in the EU must report actively exploited vulnerabilities and severe incidents affecting the security of their products: an early warning within 24 hours and a notification within 72 hours, followed by a final report. The duty sits with the manufacturer. Many Turkish manufacturers of connected devices, industrial equipment and commercial software have invested in IT security, but have no named owner and no rehearsed path for a product incident. Readiness is demonstrated in an exercise, not in a policy document: a named owner, product and version facts that can be assembled quickly, a clear decision rule, and draft text that can go out on time.', '[{"title": "Reporting has started", "explanation": "Since 11 September 2026, manufacturers of products with digital elements sold in the EU must report actively exploited vulnerabilities and severe incidents affecting the security of their products: an early warning within 24 hours and a notification within 72 hours, followed by a final report.", "page": 2}, {"title": "The duty stays with the manufacturer", "explanation": "The duty sits with the manufacturer. Many Turkish manufacturers of connected devices, industrial equipment and commercial software have invested in IT security, but have no named owner and no rehearsed path for a product incident.", "page": 2}, {"title": "Readiness is proven in an exercise", "explanation": "Readiness is demonstrated in an exercise, not in a policy document: a named owner, product and version facts that can be assembled quickly, a clear decision rule, and draft text that can go out on time.", "page": 2}]', '[]', '["Which of our products and versions are on the EU market and still supported?", "Who is the named owner of a product security incident, including outside working hours?", "How would we learn that a vulnerability is being exploited: customers, researchers, suppliers?", "Can we identify affected versions and components within hours?", "Who decides that the reporting threshold has been met?", "Who submits the report, and do they already have access to the reporting channel?", "How and when do we inform affected customers and users?", "When did we last rehearse a product incident end to end?"]', 'Desk review of official EU and Turkish sources checked on 21–23 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Cyber Resilience Act", "Product security", "EU market access"]', '["Operating model"]', '["CRA", "incident reporting", "ENISA", "manufacturers"]', 'fully_ungated', 'pdf-insights/96989394-d12c-40aa-a891-e6e5a54dbb6b/v1/Ganrich-CRA-24-Hour-Test-EN.pdf', 'Ganrich-CRA-24-Hour-Test-EN.pdf', '7eaaa1d2f5360395dfa2468f5141c7ab3b7e49db26e2cce0ef4d34abbfbc678a', 'application/pdf', 255241, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000002', '96989394-d12c-40aa-a891-e6e5a54dbb6b', 1, 'pdf-insights/96989394-d12c-40aa-a891-e6e5a54dbb6b/v1/Ganrich-CRA-24-Hour-Test-EN.pdf', 'Ganrich-CRA-24-Hour-Test-EN.pdf', '7eaaa1d2f5360395dfa2468f5141c7ab3b7e49db26e2cce0ef4d34abbfbc678a', 255241, 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('a49ad275-bff1-4cc9-851b-aab56d3463f7', 'ai-at-the-order-desk-a49ad275', 'en', 'Human-approved AI at the order desk: where WhatsApp orders meet the ERP', 'A practical view for wholesalers and distributors on what to automate, what to keep human, and how to know it works.', 'Human-approved AI at the order desk', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'October 2026', 4, 12, 'A practical view for wholesalers and distributors on what to automate, what to keep human, and how to know it works.', 'In Turkish wholesale and distribution, a large share of orders still arrives as WhatsApp messages, voice notes and phone calls, and is then re-keyed into the ERP by hand. The cost shows up as staff time, order errors and slower collections.', 'In Turkish wholesale and distribution, a large share of orders still arrives as WhatsApp messages, voice notes and phone calls, and is then re-keyed into the ERP by hand. The cost shows up as staff time, order errors and slower collections. Language models can now read these messages well enough to prepare a draft order. The value comes from drafting with human approval, not from software that invoices on its own. The right first test is small and measured: line-level accuracy and time saved on a limited group of customers, before anything touches invoices, credit or collections.', '[{"title": "Orders still arrive as messages", "explanation": "In Turkish wholesale and distribution, a large share of orders still arrives as WhatsApp messages, voice notes and phone calls, and is then re-keyed into the ERP by hand. The cost shows up as staff time, order errors and slower collections.", "page": 2}, {"title": "Drafting with approval is where value sits", "explanation": "Language models can now read these messages well enough to prepare a draft order. The value comes from drafting with human approval, not from software that invoices on its own.", "page": 2}, {"title": "Test small and measure first", "explanation": "The right first test is small and measured: line-level accuracy and time saved on a limited group of customers, before anything touches invoices, credit or collections.", "page": 2}]', '[]', '["How many orders a day arrive by message or voice, and how long does each take to key in?", "What share of order errors concern product, quantity or price?", "Is our product master clean enough to match customers’ own product names?", "Who approves draft orders, and how quickly can they do it?", "Which data would leave our systems, and on what KVKK basis?", "Which ERP do we run, and who supports it?", "What accuracy would we need to see before scaling?", "What must never be automated in our business?"]', 'Desk review of official EU and Turkish sources checked on 21–23 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Applied AI", "Operations"]', '["AI value"]', '["AI", "order desk", "WhatsApp", "ERP", "distribution"]', 'fully_ungated', 'pdf-insights/a49ad275-bff1-4cc9-851b-aab56d3463f7/v1/Ganrich-AI-Order-Desk-EN.pdf', 'Ganrich-AI-Order-Desk-EN.pdf', 'd30ee751c0c2249763a490f1c52ce466a025cf981b30975bb5e90c3dff9a3c55', 'application/pdf', 248000, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000003', 'a49ad275-bff1-4cc9-851b-aab56d3463f7', 1, 'pdf-insights/a49ad275-bff1-4cc9-851b-aab56d3463f7/v1/Ganrich-AI-Order-Desk-EN.pdf', 'Ganrich-AI-Order-Desk-EN.pdf', 'd30ee751c0c2249763a490f1c52ce466a025cf981b30975bb5e90c3dff9a3c55', 248000, 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('ef31215c-9453-4f07-8836-1699cfefa9f9', 'cbam-gercek-mi-varsayilan-mi-ef31215c', 'tr', 'Gerçek mi, varsayılan mı? Türk metal ihracatçıları için CBAM veri kararı', 'Emisyon sorusu neden AB alıcınızın uyum masasından ticari müzakere masanıza taşındı?', 'Gerçek mi, varsayılan mı', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'Ekim 2026', 5, 15, 'Emisyon sorusu neden AB alıcınızın uyum masasından ticari müzakere masanıza taşındı?', 'CBAM kesin rejimi 1 Ocak 2026’dan beri uygulanıyor. Kapsamdaki mallardan yılda 50 tonun üzerinde ithalat yapan AB ithalatçılarının yetkili CBAM beyancısı olması gerekiyor; 2026 ithalatını kapsayan ilk yıllık beyan 2027’de veriliyor.', 'CBAM kesin rejimi 1 Ocak 2026’dan beri uygulanıyor. Kapsamdaki mallardan yılda 50 tonun üzerinde ithalat yapan AB ithalatçılarının yetkili CBAM beyancısı olması gerekiyor; 2026 ithalatını kapsayan ilk yıllık beyan 2027’de veriliyor. Türk demir-çelik veya alüminyum tedarikçisi için pratik soru artık CBAM’ın uygulanıp uygulanmadığı değil. Soru, AB alıcılarına doğrulanmış gerçek emisyon verisi sunmak mı, yoksa varsayılan değerleri kullanmalarına izin vermek mi gerektiğidir. Bu, raporlama işi değil, veri maliyeti olan ticari bir karardır. Gerçek değerler kimse için otomatik olarak daha ucuz değildir. Yanıt; üretim rotasına, tesis verisinin kalitesine, bağımsız doğrulamanın maliyetine ve sözleşmenin CBAM maliyetini alıcı ile tedarikçi arasında nasıl paylaştırdığına bağlıdır.', '[{"title": "Rejim yürürlükte", "explanation": "CBAM kesin rejimi 1 Ocak 2026’dan beri uygulanıyor. Kapsamdaki mallardan yılda 50 tonun üzerinde ithalat yapan AB ithalatçılarının yetkili CBAM beyancısı olması gerekiyor; 2026 ithalatını kapsayan ilk yıllık beyan 2027’de veriliyor.", "page": 2}, {"title": "Soru ticari", "explanation": "Türk demir-çelik veya alüminyum tedarikçisi için pratik soru artık CBAM’ın uygulanıp uygulanmadığı değil. Soru, AB alıcılarına doğrulanmış gerçek emisyon verisi sunmak mı, yoksa varsayılan değerleri kullanmalarına izin vermek mi gerektiğidir. Bu, raporlama işi değil, veri maliyeti olan ticari bir karardır.", "page": 2}, {"title": "Gerçek değer otomatik olarak daha ucuz değil", "explanation": "Gerçek değerler kimse için otomatik olarak daha ucuz değildir. Yanıt; üretim rotasına, tesis verisinin kalitesine, bağımsız doğrulamanın maliyetine ve sözleşmenin CBAM maliyetini alıcı ile tedarikçi arasında nasıl paylaştırdığına bağlıdır.", "page": 2}]', '[]', '["AB müşterilerimizden hangileri eşiğin üzerinde ve hangileri gerçek veri istedi ya da isteyecek?", "AB hacmimizin çoğunu hangi ürünler ve üretim rotaları taşıyor?", "Tesis sınırımız net mi; üretim rotaları kayıtlarımızda ayrışıyor mu?", "Enerji, üretim ve öncül girdi verileri bugün nerede duruyor ve her kaynağın sahibi kim?", "Bağımsız doğrulama, kapsayacağı hacme göre bize neye mal olur?", "Sözleşmelerimiz CBAM maliyetini nasıl paylaştırıyor ve bu yeniden müzakereye açık mı?", "Öncül girdi tedarikçilerimiz güvenebileceğimiz emisyon verisi sağlıyor mu?", "Şirketimizde alıcılarla CBAM görüşmesinin sahibi kim?"]', '21–23 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["CBAM", "Carbon", "EU market access"]', '["Market entry"]', '["CBAM", "emissions", "steel", "aluminium", "EU importer"]', 'fully_ungated', 'pdf-insights/ef31215c-9453-4f07-8836-1699cfefa9f9/v1/Ganrich-CBAM-Gercek-mi-Varsayilan-mi-TR.pdf', 'Ganrich-CBAM-Gercek-mi-Varsayilan-mi-TR.pdf', '843289c8d05cde23e6f3e5730b59ab8888ceb8a9969a6df38efa3da268040b54', 'application/pdf', 266225, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000004', 'ef31215c-9453-4f07-8836-1699cfefa9f9', 1, 'pdf-insights/ef31215c-9453-4f07-8836-1699cfefa9f9/v1/Ganrich-CBAM-Gercek-mi-Varsayilan-mi-TR.pdf', 'Ganrich-CBAM-Gercek-mi-Varsayilan-mi-TR.pdf', '843289c8d05cde23e6f3e5730b59ab8888ceb8a9969a6df38efa3da268040b54', 266225, 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('37aca9ad-263a-4a2b-a414-d74293eae310', 'cra-24-saat-testi-37aca9ad', 'tr', '24 saat testi: AB’ye satış yapan üreticiler için CRA olay hazırlığı', 'Siber Dayanıklılık Yasası kapsamındaki bildirim yükümlülükleri 11 Eylül 2026’da başladı. Zor olan form değil; saatler içinde ne olduğunu ve kimin karar verdiğini bilmek.', '24 saat testi', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'Ekim 2026', 4, 12, 'Siber Dayanıklılık Yasası kapsamındaki bildirim yükümlülükleri 11 Eylül 2026’da başladı. Zor olan form değil; saatler içinde ne olduğunu ve kimin karar verdiğini bilmek.', '11 Eylül 2026’dan beri AB’de satılan dijital unsurlu ürünlerin üreticileri, ürünlerindeki aktif olarak istismar edilen açıkları ve ürün güvenliğini etkileyen ciddi olayları bildirmek zorunda: 24 saat içinde erken uyarı, 72 saat içinde bildirim ve ardından nihai rapor.', '11 Eylül 2026’dan beri AB’de satılan dijital unsurlu ürünlerin üreticileri, ürünlerindeki aktif olarak istismar edilen açıkları ve ürün güvenliğini etkileyen ciddi olayları bildirmek zorunda: 24 saat içinde erken uyarı, 72 saat içinde bildirim ve ardından nihai rapor. Yükümlülük üreticidedir. Bağlantılı cihaz, endüstriyel ekipman ve ticari yazılım üreten pek çok Türk üretici BT güvenliğine yatırım yaptı; ancak ürün olayları için belirlenmiş bir sahibi ve prova edilmiş bir yolu yok. Hazırlık bir politika belgesiyle değil, tatbikatla kanıtlanır: belirlenmiş bir sorumlu, hızla bir araya getirilebilen ürün ve sürüm bilgisi, net bir karar kuralı ve zamanında gönderilebilecek taslak metin.', '[{"title": "Bildirim başladı", "explanation": "11 Eylül 2026’dan beri AB’de satılan dijital unsurlu ürünlerin üreticileri, ürünlerindeki aktif olarak istismar edilen açıkları ve ürün güvenliğini etkileyen ciddi olayları bildirmek zorunda: 24 saat içinde erken uyarı, 72 saat içinde bildirim ve ardından nihai rapor.", "page": 2}, {"title": "Sorumluluk üreticide kalır", "explanation": "Yükümlülük üreticidedir. Bağlantılı cihaz, endüstriyel ekipman ve ticari yazılım üreten pek çok Türk üretici BT güvenliğine yatırım yaptı; ancak ürün olayları için belirlenmiş bir sahibi ve prova edilmiş bir yolu yok.", "page": 2}, {"title": "Hazırlık tatbikatla kanıtlanır", "explanation": "Hazırlık bir politika belgesiyle değil, tatbikatla kanıtlanır: belirlenmiş bir sorumlu, hızla bir araya getirilebilen ürün ve sürüm bilgisi, net bir karar kuralı ve zamanında gönderilebilecek taslak metin.", "page": 2}]', '[]', '["Hangi ürün ve sürümlerimiz AB pazarında ve hâlâ destekleniyor?", "Mesai dışı dahil, ürün güvenliği olayının belirlenmiş sorumlusu kim?", "Bir açığın istismar edildiğini nereden öğreniriz: müşteriler, araştırmacılar, tedarikçiler?", "Etkilenen sürümleri ve bileşenleri saatler içinde belirleyebilir miyiz?", "Bildirim eşiğinin aşıldığına kim karar veriyor?", "Bildirimi kim gönderiyor ve raporlama kanalına erişimi şimdiden var mı?", "Etkilenen müşterileri ve kullanıcıları nasıl ve ne zaman bilgilendiriyoruz?", "Bir ürün olayını uçtan uca en son ne zaman prova ettik?"]', '21–23 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Cyber Resilience Act", "Product security", "EU market access"]', '["Operating model"]', '["CRA", "incident reporting", "ENISA", "manufacturers"]', 'fully_ungated', 'pdf-insights/37aca9ad-263a-4a2b-a414-d74293eae310/v1/Ganrich-CRA-24-Saat-Testi-TR.pdf', 'Ganrich-CRA-24-Saat-Testi-TR.pdf', 'b3cdcc38212d074379e638b02db46ca63faa2b197df114511715fe46479704f8', 'application/pdf', 267259, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000005', '37aca9ad-263a-4a2b-a414-d74293eae310', 1, 'pdf-insights/37aca9ad-263a-4a2b-a414-d74293eae310/v1/Ganrich-CRA-24-Saat-Testi-TR.pdf', 'Ganrich-CRA-24-Saat-Testi-TR.pdf', 'b3cdcc38212d074379e638b02db46ca63faa2b197df114511715fe46479704f8', 267259, 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('ba6a12f4-dee0-406f-be47-74b19d8caac8', 'siparis-masasinda-yapay-zeka-ba6a12f4', 'tr', 'Sipariş masasında insan onaylı yapay zekâ: WhatsApp siparişleri ERP ile buluştuğunda', 'Toptancı ve distribütörler için neyin otomatikleşeceğine, neyin insanda kalacağına ve işe yaradığının nasıl anlaşılacağına dair uygulamalı bir bakış.', 'Sipariş masasında insan onaylı yapay zekâ', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-23', 'Ekim 2026', 4, 12, 'Toptancı ve distribütörler için neyin otomatikleşeceğine, neyin insanda kalacağına ve işe yaradığının nasıl anlaşılacağına dair uygulamalı bir bakış.', 'Türkiye’de toptan ticaret ve dağıtımda siparişlerin önemli bir kısmı hâlâ WhatsApp mesajı, sesli not ve telefonla geliyor ve ardından ERP’ye elle yeniden giriliyor. Bunun maliyeti personel zamanı, sipariş hataları ve geciken tahsilat olarak ortaya çıkıyor.', 'Türkiye’de toptan ticaret ve dağıtımda siparişlerin önemli bir kısmı hâlâ WhatsApp mesajı, sesli not ve telefonla geliyor ve ardından ERP’ye elle yeniden giriliyor. Bunun maliyeti personel zamanı, sipariş hataları ve geciken tahsilat olarak ortaya çıkıyor. Dil modelleri artık bu mesajları taslak sipariş hazırlayacak kadar iyi okuyabiliyor. Değer, kendi başına fatura kesen bir yazılımdan değil, insan onaylı taslak hazırlamaktan gelir. Doğru ilk test küçük ve ölçülüdür: faturaya, krediye veya tahsilata dokunmadan önce sınırlı bir müşteri grubunda satır düzeyinde doğruluk ve kazanılan zaman.', '[{"title": "Siparişler hâlâ mesajla geliyor", "explanation": "Türkiye’de toptan ticaret ve dağıtımda siparişlerin önemli bir kısmı hâlâ WhatsApp mesajı, sesli not ve telefonla geliyor ve ardından ERP’ye elle yeniden giriliyor. Bunun maliyeti personel zamanı, sipariş hataları ve geciken tahsilat olarak ortaya çıkıyor.", "page": 2}, {"title": "Değer onaylı taslakta", "explanation": "Dil modelleri artık bu mesajları taslak sipariş hazırlayacak kadar iyi okuyabiliyor. Değer, kendi başına fatura kesen bir yazılımdan değil, insan onaylı taslak hazırlamaktan gelir.", "page": 2}, {"title": "Küçük test edin, önce ölçün", "explanation": "Doğru ilk test küçük ve ölçülüdür: faturaya, krediye veya tahsilata dokunmadan önce sınırlı bir müşteri grubunda satır düzeyinde doğruluk ve kazanılan zaman.", "page": 2}]', '[]', '["Günde kaç sipariş mesaj veya sesle geliyor ve her birinin girişi ne kadar sürüyor?", "Sipariş hatalarının ne kadarı ürün, miktar veya fiyatla ilgili?", "Ürün kartlarımız, müşterilerin kendi ürün adlarını eşleştirecek kadar temiz mi?", "Taslak siparişleri kim onaylıyor ve ne kadar hızlı onaylayabilir?", "Hangi veriler sistemlerimizden çıkar ve hangi KVKK dayanağıyla?", "Hangi ERP’yi kullanıyoruz ve desteğini kim veriyor?", "Yaygınlaştırmadan önce hangi doğruluk düzeyini görmemiz gerekir?", "İşimizde asla otomatikleştirilmemesi gereken nedir?"]', '21–23 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Applied AI", "Operations"]', '["AI value"]', '["AI", "order desk", "WhatsApp", "ERP", "distribution"]', 'fully_ungated', 'pdf-insights/ba6a12f4-dee0-406f-be47-74b19d8caac8/v1/Ganrich-Siparis-Masasinda-Yapay-Zeka-TR.pdf', 'Ganrich-Siparis-Masasinda-Yapay-Zeka-TR.pdf', '6344382d2ef45d70c0ff3afb8bce0c636a9c8a946f537f4b375f4da46c6220d7', 'application/pdf', 259685, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-23T12:00:00.000Z', '2026-10-23T12:00:00.000Z');
